
-- The sample data above assigns IDs explicitly, which does not advance the BIGSERIAL
-- sequences. Re-sync them so generated IDs for new rows do not collide with the sample data.
SELECT setval('customer_id_seq', (SELECT MAX(id) FROM customer));
SELECT setval('order_id_seq', (SELECT MAX(id) FROM "order"));
SELECT setval('product_id_seq', (SELECT MAX(id) FROM product));
